DECLARE
	DBN0T VARCHAR(255);
	DBN0I VARCHAR(255);
	PARTITION_INITIAL_DAY VARCHAR(255);
	PARTITION_NAME_DAY VARCHAR(255);
	PARTITION_VALUE_DAY VARCHAR(255);
	PARTITION_NAME_NEXTDAY VARCHAR(255);
	PARTITION_VALUE_NEXTDAY VARCHAR(255);
	
BEGIN
	RAISE NOTICE '%', '==================== DBN0 Table creation ====================';

	-- Partition names
	SELECT INTO DBN0T 'dbn0_t';
	SELECT INTO DBN0I 'dbn0_i';
	SELECT INTO PARTITION_NAME_DAY 'P_'||TO_CHAR(clock_timestamp(),'YYYYMMDD');
	SELECT INTO PARTITION_VALUE_DAY TO_CHAR(clock_timestamp() + INTERVAL '1 DAY', 'YYYY-MM-DD 00:00:00');
	SELECT INTO PARTITION_INITIAL_DAY 0;
	SELECT INTO PARTITION_NAME_NEXTDAY 'P_'||TO_CHAR(clock_timestamp() + INTERVAL '1 DAY','YYYYMMDD');
	SELECT INTO PARTITION_VALUE_NEXTDAY TO_CHAR(clock_timestamp() + INTERVAL '2 DAY', 'YYYY-MM-DD 00:00:00');
	-- Create user if not exists
	IF NOT EXISTS (SELECT * FROM pg_user WHERE usename = 'dbn0_eri_ran') THEN
		CREATE USER dbn0_eri_ran WITH PASSWORD 'dbn0_eri_ran';
	END IF;
	-- Create schema if not exists
	CREATE SCHEMA IF NOT EXISTS DBN0_ERI_RAN AUTHORIZATION DBN0_ERI_RAN;
	EXECUTE format('GRANT CREATE ON TABLESPACE %s TO DBN0_ERI_RAN;', DBN0T);
	EXECUTE format('GRANT CREATE ON TABLESPACE %s TO DBN0_ERI_RAN;', DBN0I);
	-- Create sequence if not exists
	CREATE SEQUENCE IF NOT EXISTS DBN0_ERI_RAN.NA_DBN0_SEQ START WITH 1 INCREMENT BY 1 NO MAXVALUE CYCLE CACHE 10000;
	ALTER SEQUENCE DBN0_ERI_RAN.NA_DBN0_SEQ OWNER to DBN0_ERI_RAN;
	CREATE TABLE IF NOT EXISTS DBN0_ERI_RAN.EBS_EP_NGU (
