		BEGINTIME TIMESTAMP(3) NOT NULL,
		LOCALDN VARCHAR(256) NOT NULL,
		MEASOBJLDN VARCHAR(256) NOT NULL,
		ELEMENTTYPE VARCHAR(256),
		VENDORNAME VARCHAR(256),
		ENDTIME TIMESTAMP(3),
		SWVERSION VARCHAR(256),
		DURATION NUMERIC,
		SUBNETWORK1 VARCHAR(256),
		SUBNETWORK2 VARCHAR(256),
		MECONTEXT VARCHAR(256),
		MANAGEDELEMENT VARCHAR(256),
		GNBCUUPFUNCTION VARCHAR(256),
		EP_NGU VARCHAR(256)
